@prefix holon: <https://example.org/holon#> .
@prefix oe: <https://example.org/openevidence#> .
@prefix oeq: <https://example.org/openevidence/questions/> .
@prefix oegen: <https://example.org/openevidence/generated#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<https://example.org/openevidence/questions/q_alzheimer_disease_treatment> a holon:ClinicalQuestionHolon ;
  holon:hasInteriorGraph <https://example.org/openevidence/questions/q_alzheimer_disease_treatment-int> ;
  holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_alzheimer_disease_treatment-bou> ;
  holon:hasProjectionGraph <https://example.org/openevidence/questions/q_alzheimer_disease_treatment-pro> ;
  holon:hasContextGraph <https://example.org/openevidence/questions/q_alzheimer_disease_treatment-con> ;
  oe:questionText "What is the recommended first-line pharmacological treatment for Alzheimer Disease?" ;
  oe:answerText "Donepezil" .

<https://example.org/openevidence/questions/q_alzheimer_disease_treatment-int> a oe:InteriorGraph ;
  rdf:type owl:Class ;
  oe:hasFact <https://example.org/openevidence/drugs/donepezil> oe:treats <https://example.org/openevidence/diseases/alzheimer_disease> .

<https://example.org/openevidence/questions/q_alzheimer_disease_treatment-bou> a oe:BoundaryGraph ;
  rdf:type owl:Class ;
  oe:hasFact <https://example.org/openevidence/drugs/donepezil> oe:treats <https://example.org/openevidence/diseases/alzheimer_disease> .

<https://example.org/openevidence/questions/q_alzheimer_disease_treatment-pro> a oe:ProjectionGraph ;
  rdf:type owl:Class ;
  oe:hasFact <https://example.org/openevidence/drugs/donepezil> oe:treats <https://example.org/openevidence/diseases/alzheimer_disease> .

<https://example.org/openevidence/questions/q_alzheimer_disease_treatment-con> a oe:ContextGraph ;
  rdf:type owl:Class ;
  oe:hasFact <https://example.org/openevidence/drugs/donepezil> oe:treats <https://example.org/openevidence/diseases/alzheimer_disease> .

<https://example.org/openevidence/drugs/donepezil> oe:treats <https://example.org/openevidence/diseases/alzheimer_disease> .
